#include<bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int,int> pii;

int dx[]={1,-1,0,0};
int dy[]={0,0,1,-1};

struct Edge {
    int to, rev;
    ll cap;
};

class Dinic {
public:
    vector<vector<Edge>> g;
    vector<int> level, it;
    int n, s, t;
    Dinic(int n, int s, int t) : n(n), s(s), t(t) {
        g.resize(n);
        level.resize(n);
        it.resize(n);
    }
    void add_edge(int from, int to, ll cap) {
        g[from].push_back({to, (int)g[to].size(), cap});
        g[to].push_back({from, (int)g[from].size()-1, 0});
    }
    bool bfs() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto &e : g[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }
    ll dfs(int v, ll f) {
        if (v == t) return f;
        for (int &i = it[v]; i < (int)g[v].size(); ++i) {
            Edge &e = g[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                ll d = dfs(e.to, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
    ll max_flow() {
        ll flow = 0;
        while (bfs()) {
            fill(it.begin(), it.end(), 0);
            ll f;
            while ((f = dfs(s, 1e18)) > 0) flow += f;
        }
        return flow;
    }
};

int n, t;
string sci[15], cap[15];
int dis[15][15];
int dp[65][12][12][12][12];

bool valid(int x, int y) {
    if (x < 0 || y < 0 || x >= n || y >= n) return false;
    if (sci[x][y] == 'Y' || sci[x][y] == 'Z') return false;
    return true;
}

void bfs_zombie(int sx, int sy) {
    memset(dis, -1, sizeof dis);
    queue<pii> q;
    q.push({sx, sy});
    dis[sx][sy] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (valid(nx, ny) && dis[nx][ny] == -1) {
                dis[nx][ny] = dis[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (dis[i][j] == -1) dis[i][j] = 1000000000;
}

bool reachable(int tt, int x0, int y0, int x, int y) {
    if (dis[x0][y0] < tt) return false;
    if (x0 == x && y0 == y) return true;
    if (tt >= t) return false;
    if (dis[x0][y0] <= tt) return false;
    int &res = dp[tt][x0][y0][x][y];
    if (res != -1) return res;
    for (int i = 0; i < 4; ++i) {
        int nx = x0 + dx[i], ny = y0 + dy[i];
        if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
        if (sci[nx][ny] == 'Y' || sci[nx][ny] == 'Z') continue;
        if (reachable(tt + 1, nx, ny, x, y)) return res = 1;
    }
    return res = 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    memset(dp, -1, sizeof dp);
    cin >> n >> t;
    for (int i = 0; i < n; ++i) cin >> sci[i];
    for (int i = 0; i < n; ++i) cin >> cap[i];
    bool found = false;
    for (int i = 0; i < n && !found; ++i)
        for (int j = 0; j < n && !found; ++j)
            if (sci[i][j] == 'Z') { bfs_zombie(i, j); found = true; }
    vector<pii> sc, cp;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            char c = sci[i][j];
            if (c != 'Z' && c != 'Y' && c != '0') sc.push_back({i, j});
        }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            char c = cap[i][j];
            if (c != 'Z' && c != 'Y' && c != '0') cp.push_back({i, j});
        }
    Dinic flow(sc.size() + cp.size() + 2, 0, sc.size() + cp.size() + 1);
    for (int i = 0; i < (int)sc.size(); ++i) {
        ll c = sci[sc[i].first][sc[i].second] - '0';
        flow.add_edge(0, i + 1, c);
    }
    for (int i = 0; i < (int)cp.size(); ++i) {
        ll c = cap[cp[i].first][cp[i].second] - '0';
        flow.add_edge(sc.size() + 1 + i, sc.size() + cp.size() + 1, c);
    }
    for (int i = 0; i < (int)sc.size(); ++i)
        for (int j = 0; j < (int)cp.size(); ++j)
            if (reachable(0, sc[i].first, sc[i].second, cp[j].first, cp[j].second))
                flow.add_edge(i + 1, sc.size() + 1 + j, 10000000);
    cout << flow.max_flow() << endl;
}
