import java.util.*;

public class Main {
    static int[] dx = {1, -1, 0, 0};
    static int[] dy = {0, 0, 1, -1};
    static int n, t;
    static String[] sci, cap;
    static int[][] dis;
    static int[][][][][] dp;

    static class Edge {
        int to, rev;
        long cap;
        Edge(int to, int rev, long cap) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
        }
    }

    static class Dinic {
        ArrayList<ArrayList<Edge>> g;
        int[] level, it;
        int n, s, t;

        Dinic(int n, int s, int t) {
            this.n = n;
            this.s = s;
            this.t = t;
            g = new ArrayList<>(n);
            for (int i = 0; i < n; i++) g.add(new ArrayList<>());
            level = new int[n];
            it = new int[n];
        }

        void addEdge(int from, int to, long cap) {
            g.get(from).add(new Edge(to, g.get(to).size(), cap));
            g.get(to).add(new Edge(from, g.get(from).size() - 1, 0));
        }

        boolean bfs() {
            Arrays.fill(level, -1);
            Queue<Integer> q = new LinkedList<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : g.get(v)) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.add(e.to);
                    }
                }
            }
            return level[t] >= 0;
        }

        long dfs(int v, long f) {
            if (v == t) return f;
            for (int i = it[v]; i < g.get(v).size(); i++) {
                it[v] = i;
                Edge e = g.get(v).get(i);
                if (e.cap > 0 && level[v] < level[e.to]) {
                    long d = dfs(e.to, Math.min(f, e.cap));
                    if (d > 0) {
                        e.cap -= d;
                        g.get(e.to).get(e.rev).cap += d;
                        return d;
                    }
                }
            }
            return 0;
        }

        long maxFlow() {
            long flow = 0;
            while (bfs()) {
                Arrays.fill(it, 0);
                long f;
                while ((f = dfs(s, Long.MAX_VALUE)) > 0) flow += f;
            }
            return flow;
        }
    }

    static boolean valid(int x, int y) {
        if (x < 0 || y < 0 || x >= n || y >= n) return false;
        if (sci[x].charAt(y) == 'Y' || sci[x].charAt(y) == 'Z') return false;
        return true;
    }

    static void bfsZombie(int sx, int sy) {
        dis = new int[n][n];
        for (int i = 0; i < n; i++) Arrays.fill(dis[i], -1);
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{sx, sy});
        dis[sx][sy] = 0;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1];
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                if (valid(nx, ny) && dis[nx][ny] == -1) {
                    dis[nx][ny] = dis[x][y] + 1;
                    q.add(new int[]{nx, ny});
                }
            }
        }
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (dis[i][j] == -1) dis[i][j] = 1000000000;
    }

    static boolean reachable(int tt, int x0, int y0, int x, int y) {
        if (dis[x0][y0] < tt) return false;
        if (x0 == x && y0 == y) return true;
        if (tt >= t) return false;
        if (dis[x0][y0] <= tt) return false;
        if (dp[tt][x0][y0][x][y] != -1) return dp[tt][x0][y0][x][y] == 1;
        for (int i = 0; i < 4; i++) {
            int nx = x0 + dx[i], ny = y0 + dy[i];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (sci[nx].charAt(ny) == 'Y' || sci[nx].charAt(ny) == 'Z') continue;
            if (reachable(tt + 1, nx, ny, x, y)) {
                dp[tt][x0][y0][x][y] = 1;
                return true;
            }
        }
        dp[tt][x0][y0][x][y] = 0;
        return false;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        sci = new String[n];
        cap = new String[n];
        for (int i = 0; i < n; i++) sci[i] = sc.next();
        for (int i = 0; i < n; i++) cap[i] = sc.next();

        // Initialize dp with -1
        dp = new int[65][12][12][12][12];
        for (int a = 0; a < 65; a++)
            for (int b = 0; b < 12; b++)
                for (int c = 0; c < 12; c++)
                    for (int d = 0; d < 12; d++)
                        Arrays.fill(dp[a][b][c][d], -1);

        boolean found = false;
        for (int i = 0; i < n && !found; i++)
            for (int j = 0; j < n && !found; j++)
                if (sci[i].charAt(j) == 'Z') {
                    bfsZombie(i, j);
                    found = true;
                }

        ArrayList<int[]> scList = new ArrayList<>();
        ArrayList<int[]> cpList = new ArrayList<>();
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                char c = sci[i].charAt(j);
                if (c != 'Z' && c != 'Y' && c != '0') scList.add(new int[]{i, j});
            }
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                char c = cap[i].charAt(j);
                if (c != 'Z' && c != 'Y' && c != '0') cpList.add(new int[]{i, j});
            }

        int S = 0;
        int T = scList.size() + cpList.size() + 1;
        Dinic flow = new Dinic(scList.size() + cpList.size() + 2, S, T);

        for (int i = 0; i < scList.size(); i++) {
            int[] p = scList.get(i);
            long c = sci[p[0]].charAt(p[1]) - '0';
            flow.addEdge(0, i + 1, c);
        }
        for (int i = 0; i < cpList.size(); i++) {
            int[] p = cpList.get(i);
            long c = cap[p[0]].charAt(p[1]) - '0';
            flow.addEdge(scList.size() + 1 + i, T, c);
        }
        for (int i = 0; i < scList.size(); i++) {
            int[] p1 = scList.get(i);
            for (int j = 0; j < cpList.size(); j++) {
                int[] p2 = cpList.get(j);
                if (reachable(0, p1[0], p1[1], p2[0], p2[1]))
                    flow.addEdge(i + 1, scList.size() + 1 + j, 10000000);
            }
        }
        System.out.println(flow.maxFlow());
        sc.close();
    }
}
